export async function ensureChapter(prisma: PrismaClient, chapterSlug: string) {
  if (!chapterSlug) return null;

  // 1. Try to find published chapter directly in DB
  let chapter = await prisma.chapter.findFirst({
    where: {
      slug: chapterSlug,
    },
    include: {
      topics: true,
    },
  });

  if (chapter) {
    if (!chapter.isPublished) {
      chapter = await prisma.chapter.update({
        where: { id: chapter.id },
        data: { isPublished: true },
        include: { topics: true },
      });
    }
    return chapter;
  }

  // 2. If not found in DB, check curriculum registry
  const meta = KNOWN_CHAPTERS[chapterSlug];
  if (!meta) return null;

  const subjectMeta = KNOWN_SUBJECTS[meta.subjectSlug] ?? KNOWN_SUBJECTS['science'];
  const subject = await prisma.subject.upsert({
    where: { slug: subjectMeta.slug },
    update: { isPublished: true },
    create: {
      name: subjectMeta.name,
      slug: subjectMeta.slug,
      classLevel: subjectMeta.classLevel,
      description: subjectMeta.description,
      isPublished: true,
      sortOrder: subjectMeta.sortOrder,
    },
  });

  chapter = await prisma.chapter.upsert({
    where: {
      subjectId_slug: {
        subjectId: subject.id,
        slug: meta.slug,
      },
    },
    update: {
      isPublished: true,
      title: meta.title,
    },
    create: {
      subjectId: subject.id,
      title: meta.title,
      slug: meta.slug,
      ncertChapterNumber: meta.ncertChapterNumber,
      isPublished: true,
      sortOrder: meta.ncertChapterNumber,
    },
    include: {
      topics: true,
    },
  });

  // 3. Ensure topics are created
  if (meta.lessons.length > 0) {
    await prisma.topic.createMany({
      data: meta.lessons.map((lesson) => ({
        chapterId: chapter.id,
        title: lesson.title,
        slug: lesson.slug,
        sortOrder: lesson.sortOrder,
        isPublished: true,
      })),
      skipDuplicates: true,
    });

    await prisma.topic.updateMany({
      where: {
        chapterId: chapter.id,
        slug: { in: meta.lessons.map((lesson) => lesson.slug) },
      },
      data: { isPublished: true },
    });
  }

  return prisma.chapter.findUnique({
    where: { id: chapter.id },
    include: { topics: true },
  });
}
